const $=id=>document.getElementById(id),norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const examples=[{id:'ex1',title:'Nova biblioteca abre as portas no bairro',date:'2026-11-10',people:['Marina Exemplo'],section:'Educação',show:'Jornal da Cidade',duration:'02:35',video:'',poster:'',transcript:'EXEMPLO FICTÍCIO. Uma reportagem de demonstração sobre uma biblioteca imaginária. Não corresponde a pessoas, imagens ou acontecimentos reais.',example:true},{id:'ex2',title:'Moradores discutem o transporte público',date:'2026-11-09',people:['João Demonstração'],section:'Mobilidade',show:'Jornal da Noite',duration:'03:10',video:'',poster:'',transcript:'EXEMPLO FICTÍCIO. Moradores de um bairro imaginário comentam o transporte. Texto criado apenas para testar o campo de busca.',example:true},{id:'ex3',title:'Feira reúne produtores da região',date:'2026-10-24',people:['Marina Exemplo','Pedro Fictício'],section:'Economia',show:'Jornal da Cidade',duration:'01:55',video:'',poster:'',transcript:'EXEMPLO FICTÍCIO. Feira imaginária de produtores. Nenhum fato ou número desta demonstração deve ser usado em reportagens.',example:true}];let records=[];try{records=JSON.parse(localStorage.getItem('g6-tv-acervo-v1')||'[]');if(!Array.isArray(records))records=[]}catch{}const all=()=>[...records,...examples];
function url(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function distance(a,b){let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));row=next}return row[b.length]}
function match(text,query){const hay=norm(text),words=hay.split(/\s+/);return norm(query).split(/\s+/).filter(Boolean).every(t=>hay.includes(t)||(t.length>=4&&words.some(w=>Math.abs(t.length-w.length)<=1&&distance(t,w)<=1)))}
function fillFilters(){for(const [id,key,def]of [['person','people','Todas'],['section','section','Todas'],['show','show','Todos']]){const prev=$(id).value;const vals=[...new Set(all().flatMap(r=>r[key]))].sort((a,b)=>a.localeCompare(b,'pt'));$(id).innerHTML='<option value="">'+def+'</option>'+vals.map(v=>'<option>'+esc(v)+'</option>').join('');if(vals.includes(prev))$(id).value=prev}$('names').innerHTML=[...new Set(all().flatMap(r=>r.people))].map(p=>'<option value="'+esc(p)+'">').join('')}
function filtered(){return all().filter(r=>{const date=r.date.split('-').reverse().join('/');return match([r.title,r.people.join(' '),r.transcript,r.date,date].join(' '),$('q').value)&&(!$('from').value||r.date>=$('from').value)&&(!$('to').value||r.date<=$('to').value)&&(!$('person').value||r.people.includes($('person').value))&&(!$('section').value||r.section===$('section').value)&&(!$('show').value||r.show===$('show').value)}).sort((a,b)=>b.date.localeCompare(a.date))}
function render(){if($('from').value&&$('to').value&&$('from').value>$('to').value){$('count').textContent='A data inicial precisa vir antes da data final.';$('results').replaceChildren();return}const list=filtered();$('count').textContent=list.length+' reportagem(ns) encontrada(s).';$('results').innerHTML=list.length?list.map(r=>'<article class="card">'+(url(r.poster)?'<img class="thumb" style="width:100%;object-fit:cover" alt="Miniatura da reportagem" src="'+esc(url(r.poster))+'">':'<div class="thumb">'+(r.example?'EXEMPLO FICTÍCIO · SEM VÍDEO':'SEM MINIATURA')+'</div>')+'<h3>'+esc(r.title)+'</h3><p>'+esc(r.date.split('-').reverse().join('/'))+' · '+esc(r.duration)+'</p><p>'+esc(r.people.join(', ')||'Nenhuma pessoa cadastrada')+'</p><p>'+esc(r.section)+' · '+esc(r.show)+'</p><button data-open="'+esc(r.id)+'">Ver reportagem</button></article>').join(''):'<p>Nenhuma reportagem corresponde aos filtros. Tente menos palavras ou um período maior.</p>'}
for(const id of ['q','from','to','person','section','show'])$(id).addEventListener('input',render);$('reset').onclick=()=>{for(const id of ['q','from','to','person','section','show'])$(id).value='';render()};
$('results').onclick=e=>{const id=e.target.dataset.open;if(!id)return;const r=all().find(r=>r.id===id);if(!r)return;const video=url(r.video);$('detailBody').innerHTML='<h2>'+esc(r.title)+'</h2><p>'+esc(r.date.split('-').reverse().join('/'))+' · '+esc(r.duration)+' · '+esc(r.people.join(', '))+'</p>'+(video?'<video controls preload="none" src="'+esc(video)+'"></video><p class="small">Se não tocar, o endereço pode exigir acesso ou não ser um vídeo direto compatível.</p><a class="button" target="_blank" rel="noopener" href="'+esc(video)+'">Abrir arquivo</a><button class="secondary" id="copy">Copiar link</button><p id="copyStatus" role="status"></p>':'<p class="panel">Este registro é fictício e não tem um vídeo real associado.</p>')+'<h3>Transcrição</h3><pre>'+esc(r.transcript||'Sem transcrição cadastrada.')+'</pre>';if(video)$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(video);$('copyStatus').textContent='Link copiado.'}catch{$('copyStatus').textContent='Copie este endereço: '+video}};$('detail').showModal()};$('close').onclick=()=>{const v=$('detail').querySelector('video');if(v)v.pause();$('detail').close()};$('detail').addEventListener('close',()=>{const v=$('detail').querySelector('video');if(v)v.pause()});
$('add').onsubmit=e=>{e.preventDefault();const video=url($('video').value),poster=$('poster').value.trim();if(!video||(poster&&!url(poster))){$('saveStatus').textContent='Use links que comecem com http:// ou https://.';return}const known=all().flatMap(r=>r.people),people=$('people').value.split(';').map(x=>x.trim()).filter(Boolean).map(p=>known.find(k=>norm(k)===norm(p))||p);const r={id:'local-'+Date.now(),title:$('title').value.trim(),date:$('date').value,duration:$('duration').value,people:[...new Set(people)],section:$('editoria').value.trim(),show:$('jornal').value.trim(),video,poster,transcript:$('transcript').value.trim(),example:false};try{localStorage.setItem('g6-tv-acervo-v1',JSON.stringify([r,...records]));records.unshift(r);$('add').reset();$('saveStatus').textContent='Reportagem cadastrada apenas neste navegador.';fillFilters();render()}catch{$('saveStatus').textContent='Não foi possível salvar neste navegador. O cadastro não foi concluído.'}};fillFilters();render();
